def solve_n_queens(n, fixed):
    def is_safe(board, row, col):
        for r in range(row):
            c = board[r]
            if c == col or abs(c - col) == abs(r - row):
                return False
        return True

    def solve(row, board):
        if row == n:
            return board

        if row in fixed:
            col = fixed[row]
            if is_safe(board, row, col):
                board.append(col)
                res = solve(row + 1, board)
                if res: return res
                board.pop()
            return None

        for col in range(n):
            if is_safe(board, row, col):
                board.append(col)
                res = solve(row + 1, board)
                if res: return res
                board.pop()
        return None

    return solve(0, [])

print(solve_n_queens(13, {1: 12, 11: 1}))
